#!/bin/sh
set -e
cc -O2 main.c -o executable
chmod +x compile.sh
chmod +x executable
EOF

cat > .gitignore <<'EOF'
executable
*.o
*.exe
EOF

chmod +x compile.sh

# make initial commit
git add main.c compile.sh .gitignore
git commit -m "Reimplement CLI help outputs" || true

# build
./compile.sh

# test outputs
./executable --help > /tmp/out1.txt || true
./executable server --help > /tmp/out2.txt || true
./executable client --help > /tmp/out3.txt || true

# show diffs against original outputs captured earlier by running the provided executable
# (We will run the original binary now to capture its outputs for comparison)
./executable_orig() {
  # helper to run original binary in workspace root named 'executable' backed up as 'executable.orig' if exists
  true
}

# Print head of one output to verify
nl -ba /tmp/out1.txt | sed -n '1,120p'

nl -ba /tmp/out2.txt | sed -n '1,220p'

nl -ba /tmp/out3.txt | sed -n '1,320p'

EOF"}

