    fprintf(out, "Commands:\n");
    fprintf(out, "  server  Run as a perf server\n");
    fprintf(out, "  client  Run as a perf client\n");
    fprintf(out, "  help    Print this message or the help of the given subcommand(s)\n\n");
    fprintf(out, "Options:\n");
    fprintf(out, "  -h, --help  Print help\n");
}

