int main(int argc, char** argv){
    if(argc <= 1){
        print_general_help(stdout);
        return 2;
    }
    // handle top-level help flags
    if(strcmp(argv[1], "-h") == 0 || strcmp(argv[1], "--help") == 0){
        print_general_help(stdout);
        return 0;
    }
    if(strcmp(argv[1], "help") == 0){
        if(argc == 2){
            print_general_help(stdout);
            return 0;
        } else {
            if(strcmp(argv[2], "server") == 0){ print_server_help(stdout); return 0; }
            if(strcmp(argv[2], "client") == 0){ print_client_help(stdout); return 0; }
            // unknown subcommand
            print_general_help(stdout);
            return 2;
        }
    }
    if(strcmp(argv[1], "server") == 0){
        // if next arg is help flag anywhere, print server help
        for(int i=2;i<argc;i++){
            if(strcmp(argv[i], "-h")==0 || strcmp(argv[i], "--help")==0){ print_server_help(stdout); return 0; }
        }
        // For simplicity, when invoked as server without --help, do nothing and return 0
        return 0;
    }
    if(strcmp(argv[1], "client") == 0){
        for(int i=2;i<argc;i++){
            if(strcmp(argv[i], "-h")==0 || strcmp(argv[i], "--help")==0){ print_client_help(stdout); return 0; }
        }
        return 0;
    }
    // unknown command
    print_general_help(stdout);
    return 2;
}
